for(const t of topics){
  const dir=`course/drafts/${t.id}`;
  if(!fs.existsSync(dir)) continue;
  const expected=new Set([`${t.id}-overview.md`,`${t.id}-concepts.md`,`${t.id}-practice.md`,`${t.id}-interview.md`,...t.refs.map(g=>`${t.id}-reference-${g.id}.md`)]);
  if(t.id==='t12-006') for(const c of caseStudies) expected.add(`${t.id}-practice-${c.id}.md`);
  for(const file of fs.readdirSync(dir)) if(file.startsWith(`${t.id}-`)&&file.endsWith('.md')&&!expected.has(file)) fs.unlinkSync(path.join(dir,file));
}

// Extend cross-topic interview practice with additional complete problem units.
const interviewPath='curriculum/manifests/testing-and-senior-interviews/t10-009.json';
const interview=JSON.parse(fs.readFileSync(interviewPath,'utf8'));
const moreProblems=[
 ['ambiguous-payment-timeout','Resolve a payment request whose response timed out','advanced','payment idempotency key; ambiguous commit; ledger state; provider reconciliation','An API receives a payment request. The provider may have charged the card, but the response timed out. Design safe retry, user-visible status, and reconciliation behavior.'],
 ['multi-tenant-noisy-neighbor','Protect a multi-tenant service from a noisy tenant','advanced','tenant identity enforcement; fairness and quotas; workload isolation; per-tenant observability','One tenant creates a sudden workload spike that raises latency for every customer. Explain diagnosis, containment, fairness, and longer-term partitioning decisions.'],
 ['database-queue-dual-write','Prevent lost events between a database and a broker','advanced','transactional outbox; duplicate delivery; idempotent consumer; reconciliation','An API writes an order to SQL Server and publishes an event to a broker. A process crash between these operations can lose or duplicate the event. Design the path.'],
 ['regional-failover-recovery','Design and test regional recovery','advanced','RTO and RPO; data replication and ownership; routing and promotion; failback validation','A regional outage affects a customer-facing service. Define the failover decision, data-loss boundary, customer communication, and safe return to the primary region.'],
 ['api-evolution-mixed-clients','Evolve an API used by old and new clients','intermediate','contract compatibility; additive then removal sequence; capability detection; telemetry and deprecation','A mobile client may remain installed for months while the backend must change a response and a required field. Propose a migration that avoids breaking deployed clients.'],
 ['live-leaderboard-hot-key','Design a live leaderboard without one hot key','advanced','partitioned aggregation; approximate versus exact ranking; update frequency; read model freshness','A global game leaderboard receives frequent score updates and millions of reads. Explain ingestion, ranking, hot-key control, consistency, and cost.'],
 ['recommendation-feedback-loop','Diagnose a recommendation system feedback loop','advanced','candidate generation and ranking; exposure bias; offline and online evaluation; safety and user controls','A recommendation system increasingly shows only already popular items. Explain data, model, evaluation, product, and monitoring changes that address the feedback loop.'],
 ['production-latency-after-release','Investigate a latency regression after release','intermediate','user-centered SLI and percentiles; traces and dependency breakdown; rollback and feature flags; data-plane versus client evidence','p50 latency is unchanged, but users report delays after a deployment. Describe evidence collection, blast-radius reduction, rollback decision, and follow-up.'],
];
interview.practiceProblems ??=[];
for(const [id,name,difficulty,patterns,statement] of moreProblems) if(!interview.practiceProblems.some(p=>p.id===id)) interview.practiceProblems.push({id,name,difficulty,patterns:patterns.split('; '),statement,constraints:['State assumptions and the correctness property before selecting technology.','Explain normal, peak, failure, recovery, and observability behavior.'],examples:[{input:'The interviewer adds a failure, traffic spike, or compatibility constraint midway through the design.',output:'Revisit only the affected assumptions, trace the changed path, and explain the new tradeoff and validation plan.'}],sourceUrls:[handbook,official.googleSre,official.azureArch,official.azureWell]});
interview.sourceSnapshot.urls=[...new Set([...interview.sourceSnapshot.urls,handbook,official.googleSre,official.azureArch,official.azureWell])];
interview.comparisonSources=[...new Set([...(interview.comparisonSources??[]),handbook,official.googleSre,official.azureArch,official.azureWell])];
fs.writeFileSync(interviewPath,JSON.stringify(interview,null,2)+'\n');

const scenarioGuides={
 'ambiguous-payment-timeout':['Do not infer failure from the missing response. Give every logical payment attempt a stable idempotency key, persist the operation state, and query or reconcile the provider before creating another charge. Model authorized, captured, failed, and unknown outcomes explicitly; return a status resource while reconciliation continues. Never retry a new charge blindly.','The provider may have succeeded. Preserve the same operation key, inspect authoritative provider status, and reconcile against the internal ledger. If status remains unknown, hold the operation for bounded retry/review and tell the user it is pending.'],
 'multi-tenant-noisy-neighbor':['First contain the spike with per-tenant request, concurrency, and expensive-operation quotas while preserving a fair share for others. Trace and measure the source; inspect tenant-level latency and resource use with bounded-cardinality telemetry. Then evaluate workload isolation, partitioning, and tenant placement against measured skew and service objectives.','Protect shared capacity immediately with bounded per-tenant quotas and admission control. Check whether the workload is legitimate or abusive, and whether a particular key or query causes amplification. Partition only if evidence shows the shared pool cannot meet fairness and SLO needs.'],
 'database-queue-dual-write':['Write the order and an outbox row in one local database transaction. A publisher reads pending rows, publishes at least once, and marks progress; a crash may repeat publication. Consumers deduplicate with the stable event ID and commit their side effect with their consumed marker where possible. Monitor outbox age and reconcile missing projections.','The database transaction makes business state and intent-to-publish atomic. It does not make broker delivery exactly once. Replays are expected; event IDs and idempotent consumers make the business effect safe.'],
 'regional-failover-recovery':['Define the failure declaration authority and thresholds, then compare observed replication lag with RPO before promotion. Route traffic only after the standby is ready and data ownership is fenced. Communicate impact, verify critical flows, and track reconciliation. Failback is a separate migration: synchronize data, test the target, and switch deliberately.','A recovery plan states measured RTO/RPO, promotion and fencing rules, data-loss acceptance, customer status communication, and validation. A DNS change alone is not a failover plan. Exercise restore and failback regularly.'],
 'api-evolution-mixed-clients':['Prefer additive compatible changes: add optional response fields, tolerate unknown fields, and avoid changing existing meanings. If a required behavior is needed, introduce a new version or capability negotiation and migrate clients over a measured period. Observe old-client use before removing a contract.','Keep old clients valid through the migration window. Add a new optional field/endpoint first; update clients; track adoption; then deprecate and remove only after usage and policy permit. Mobile updates are not instantaneous.'],
 'live-leaderboard-hot-key':['Separate score ingestion from ranking reads. Partition events by player or match, aggregate incrementally, and avoid a single globally updated counter. Decide whether ranking is exact or approximate and at what freshness. Precompute top ranges, shard score buckets or use a specialized ranking approach; test ties, corrections, and late events.','The global ranking key is the bottleneck. Partition updates by entity and periodically or incrementally merge sorted ranges; define exactness and freshness. A simple cache helps reads but does not remove the hot write path.'],
 'recommendation-feedback-loop':['Log exposure as well as clicks so non-clicks have context; evaluate candidate coverage, ranking quality, diversity, and safety separately. Use randomized or controlled exploration when appropriate, segment results, and compare offline metrics with online user outcomes. Add user controls and monitor concentration, not only click-through rate.','Popularity can reinforce exposure and future interaction. Measure what was shown, add suitable exploration and diversity constraints, evaluate by cohort, and watch harm or concentration metrics. Click-through alone is not a sufficient objective.'],
 'production-latency-after-release':['Check p95/p99 and user journey metrics by route, region, device, and release cohort. Compare traces and resource saturation to the prior version; distinguish server, database, dependency, and browser main-thread time. Stop expansion or roll back when impact exceeds policy; preserve evidence, then reproduce and add a regression guard.','Unchanged p50 does not rule out tail regression. Segment by cohort and inspect trace span duration, errors, queue age, saturation, and real-user/browser timing. Reduce blast radius and rollback based on the service objective.']
};
const practiceDir='course/drafts/t10-009';fs.mkdirSync(practiceDir,{recursive:true});
for(const [id,name,difficulty,patterns,statement] of moreProblems){
 const taskTitle=`architecture interviews tradeoffs requirements and constraints — Problem: ${name}`;
 const [approach,answer]=scenarioGuides[id];
 const file=`${practiceDir}/t10-009-practice-${id}.md`;
 fs.writeFileSync(file,`# ${taskTitle}\n\nSources: ${citeInterview()}\n\n## Goals\n\nPractice ${patterns.split('; ').join(', ')} under interview constraints.\n\n## Worked example\n\n${statement}\n\n${approach}\n\n## Exercises\n\n1. State one functional goal, one invariant, and two measurable quality targets.\n2. Draw the normal write/read path and identify the authoritative state.\n3. Introduce a timeout or partial failure. Explain what is known, unknown, and safe to retry.\n4. Name the security and privacy boundaries and the telemetry needed to operate the design.\n5. State one alternative and the evidence that would make you choose it.\n\n## Progressive hints\n\nStart from the user-visible invariant. Separate acceptance from completion. Follow data through every durable boundary. Treat timeouts as ambiguous and include a recovery path.\n\n## Complete solutions\n\n1. ${answer}\n2. State the owner and transaction boundary; distinguish derived data from authoritative data.\n3. Retry only with stable idempotency or outcome verification. Define bounded deadlines, deduplication, and reconciliation.\n4. Enforce authorization on the server at each resource/action. Observe user outcomes, saturation, latency, and recovery age without logging credentials or uncontrolled personal data.\n5. Compare alternatives against consistency, workload, operational maturity, failure behavior, and cost.\n\n## Tests and edge cases\n\nTest duplicate submission, lost acknowledgement after success, dependency outage, replay after restart, peak load, partial rollback, access by another tenant, and recovery after data corruption or regional loss.\n\n## Reflection questions\n\nWhich assumption could change your design? Which failure could cause an irreversible side effect? How will production evidence confirm the design meets its objective?\n`);
}
function citeInterview(){return [handbook,official.googleSre,official.azureArch,official.azureWell].map(u=>`[source](${u})`).join(', ')}

// Stack-specific system-design connections. These extend existing lessons in
// place so the general architecture material connects to the learner's stack.
const extensions=[
 ['course/drafts/t01-016/t01-016-concepts.md','## .NET async behavior as a capacity boundary',`Async I/O lets a request release its worker thread while waiting; it does not remove downstream limits or make CPU-heavy work parallel. In a service, propagate the request cancellation token to cooperative I/O, apply an end-to-end deadline, and bound concurrent work. Avoid sync-over-async and unbounded task creation, which can exhaust ThreadPool workers or memory under load. A client disconnect may cancel work that has not committed; after durable acceptance, background work may intentionally outlive the HTTP request. Decide that boundary explicitly. See [Task-based Asynchronous Pattern](https://learn.microsoft.com/en-us/dotnet/standard/asynchronous-programming-patterns/task-based-asynchronous-pattern-tap) and [common async bugs](https://learn.microsoft.com/en-us/dotnet/standard/asynchronous-programming-patterns/common-async-bugs).`],
 ['course/drafts/t02-016/t02-016-concepts.md','## System-design tracing across the .NET request path',`Instrument an inbound request, database operation, and outbound dependency as one causal path. When work crosses a broker, propagate trace context in message metadata and start a consumer activity on receipt; a queue boundary is not automatically a child span in another process. Use a stable service identity and low-cardinality route/operation attributes. Track request outcomes and duration as metrics, use traces to localize a slow span, and keep sensitive user data and credentials out of baggage and telemetry. Sampling changes which traces are retained, so preserve aggregate metrics for population-wide SLOs. [OpenTelemetry .NET](https://opentelemetry.io/docs/languages/dotnet/) · [distributed tracing instrumentation](https://learn.microsoft.com/en-us/dotnet/core/diagnostics/distributed-tracing-instrumentation-walkthroughs).`],
 ['course/drafts/t02-016/t02-016-interview.md','## System-design scenario: trace a request through HTTP, SQL, and a worker',`A good response distinguishes aggregate signals from request-level evidence. Start with the user-facing SLI, inspect trace sampling and service/resource identity, follow the request span into database and outbound HTTP spans, then trace queued work using propagated context or a causal link. Check duration, errors, saturation, and queue age. Avoid adding customer IDs as metric dimensions; use access-controlled trace/log correlation when individual diagnosis is necessary. Health probes answer readiness/liveness questions and do not replace these signals. [OpenTelemetry .NET](https://opentelemetry.io/docs/languages/dotnet/).`],
 ['course/drafts/t02-021/t02-021-concepts.md','## System-design deployment: readiness, draining, and compatible releases',`A production ASP.NET Core instance should receive traffic only after startup validation and required initialization finish. During shutdown, stop accepting new work and allow bounded in-flight requests to drain; durable background work needs its own checkpoint/retry protocol. Behind a reverse proxy, configure trusted forwarded headers deliberately so scheme, host, and client-address interpretation cannot be spoofed. For rolling deployment, keep old and new code compatible with the shared database and API clients: expand schema first, deploy code that can read both shapes, backfill, then contract after old consumers are gone. A binary rollback cannot reverse an incompatible data mutation. [ASP.NET Core health checks](https://learn.microsoft.com/en-us/aspnet/core/host-and-deploy/health-checks) · [ASP.NET Core environments](https://learn.microsoft.com/en-us/aspnet/core/fundamentals/environments).`],
 ['course/drafts/t04-008/t04-008-concepts.md','## System-design boundary: EF Core transaction and external delivery',`An EF Core transaction can make related database changes atomic on the same transactional resource. It cannot atomically commit a message to an unrelated broker or an email provider. Write an outbox record with the domain change in one database transaction; publish it asynchronously and expect possible duplicate delivery. Give each event a stable identifier and make the consumer's effect idempotent. Keep broker calls outside the database transaction so network delay does not extend locks. Recovery includes retrying pending outbox rows and reconciling downstream state. This pattern composes local transactions with at-least-once delivery; it is not end-to-end exactly-once execution. [EF Core transactions](https://learn.microsoft.com/en-us/ef/core/saving/transactions).`],
 ['course/drafts/t07-009/t07-009-concepts.md','## System-design view: rendering is part of the request path',`Choose rendering per user journey and operating constraint. Server rendering can return useful HTML earlier, but adds server capacity, data-fetch latency, and cache/privacy decisions; static output shifts work to build or revalidation time but may be stale; client rendering depends on JavaScript delivery and browser work. Streaming can release ready portions sooner but still needs a compatible host and carefully chosen boundaries. Hydration requires the initial client render to agree with server markup. Keep personalized HTML out of shared caches unless the cache key and authorization model are correct. Treat initial HTML, JavaScript chunks, API data, and CDN cache as one release graph. [React DOM server APIs](https://react.dev/reference/react-dom/server) · [React Suspense](https://react.dev/reference/react/Suspense).`],
 ['course/drafts/t07-013/t07-013-interview.md','## System-design scenario: React client, ASP.NET Core API, and tenant boundary',`The browser renders controls and may hide unavailable actions for usability, but every API operation must authenticate the caller and authorize the requested tenant/resource on the server. The React app should send only the minimum identifiers and data needed; the API derives trusted identity from its validated credential and checks membership/permission against authoritative data. Avoid putting tenant secrets or privileged upstream keys in the client bundle. For multi-tenant caching, include a trustworthy tenant/authorization scope in the cache design or cache only public data. [OWASP Authorization](https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html) · [React Server Functions](https://react.dev/reference/rsc/use-server).`],
 ['course/drafts/t07-023/t07-023-concepts.md','## System-design view: React data caches and backend ownership',`A route loader, Server Component, browser query cache, CDN, and API database are different layers with different lifetimes. Decide which layer owns each representation, how mutation invalidates or revalidates it, and whether a stale value is safe. User-specific data needs authorization-aware cache keys and private/shared cache rules; do not assume framework caching is automatically per-user. Mutations should be authorized and validated by the server even when initiated by a route action or Server Function. During deployment, retain old asset files while cached HTML may reference them, and evolve API/schema contracts so old clients and new servers can overlap safely. [React application guidance](https://react.dev/learn/creating-a-react-app) · [Next.js App Router](https://nextjs.org/docs/app).`],
];
